/* BizMitra V2 Final — Supabase-backed business workspace. Public publishable key only. */
const SUPABASE_URL='https://bfntxdvkxoqirvgjqfvw.supabase.co';
const SUPABASE_KEY='sb_publishable_6mGeXcgTuw5fJylKT8O43Q_OWY2afO2';
const sb=window.supabase.createClient(SUPABASE_URL,SUPABASE_KEY);
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const state={user:null,business:null,subscription:null,customers:[],products:[],invoices:[],items:[],expenses:[],payments:[],movements:[],reminders:[],page:'dashboard',theme:localStorage.getItem('bm-theme')||'light'};
const tables=['customers','products','invoices','invoice_items','expenses','payment_records','inventory_movements','payment_reminders'];
const money=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:state.business?.currency||'INR',maximumFractionDigits:2}).format(Number(n||0));
const date=v=>v?new Date(v+'T00:00:00').toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'}):'—';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const toast=m=>{let t=$('#toast');t.textContent=m;t.classList.add('show');clearTimeout(window._toast);window._toast=setTimeout(()=>t.classList.remove('show'),2800)};
const err=e=>{console.error(e);toast(e?.message||'Something went wrong. Please try again.')};
const today=()=>new Date().toISOString().slice(0,10);
// Plan gates: only an active, non-expired subscription unlocks Pro. Checkout is not enabled yet.
const subscriptionIsActive=()=>{const s=state.subscription;if(!s||s.status!=='active')return false;if(s.plan==='lifetime')return true;return !s.expires_at||new Date(s.expires_at).getTime()>Date.now();};
const currentPlan=()=>subscriptionIsActive()?(state.subscription?.plan||'free'):'free';
const isPro=()=>currentPlan()!=='free';
const freeInvoiceLimit=3,freeCustomerLimit=25,freeProductLimit=25;
const invoiceMonth=()=>new Date().toISOString().slice(0,7);
const invoicesThisMonth=()=>state.invoices.filter(i=>(i.created_at||i.issue_date||'').slice(0,7)===invoiceMonth()&&i.status!=='cancelled').length;
function requirePro(feature){if(isPro())return true;toast(`${feature} is a Pro feature. See Plans & billing.`);setPage('plans');return false;}
function checkFreeLimit(kind){if(isPro())return true;const limits={customers:freeCustomerLimit,products:freeProductLimit,invoices:freeInvoiceLimit};const count={customers:state.customers.length,products:state.products.length,invoices:invoicesThisMonth()}[kind];if(count>=limits[kind]){toast(`Free plan limit reached: ${limits[kind]} ${kind==='invoices'?'invoices this month':kind}. Upgrade to Pro for more.`);setPage('plans');return false;}return true;}
function applyTheme(){document.body.classList.toggle('dark',state.theme==='dark');localStorage.setItem('bm-theme',state.theme)}
function setPage(p){state.page=p;$('#sidebar').classList.remove('open');$$('.nav-item[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===p));$('#pageTitle').textContent=({dashboard:'Overview',invoices:'Invoices',customers:'Customers',products:'Products & services',inventory:'Inventory',expenses:'Expenses',reports:'Reports & GST',plans:'Plans & billing',settings:'Business settings'})[p];render()}
async function loadAll(){for(const t of tables){const {data,error}=await sb.from(t).select('*').order('created_at',{ascending:false});if(error)throw error;state[t]=data||[];}state.items=state.invoice_items;state.payments=state.payment_records;state.movements=state.inventory_movements;state.reminders=state.payment_reminders;const {data:b,error:be}=await sb.from('businesses').select('*').maybeSingle();if(be)throw be;state.business=b;if(!b){const {data,error}=await sb.from('businesses').insert({owner_id:state.user.id,business_name:'My Business',owner_name:state.user.user_metadata?.display_name||''}).select().single();if(error)throw error;state.business=data;}const {data:s,error:se}=await sb.from('subscriptions').select('*').maybeSingle();if(se)throw se;state.subscription=s;}
async function refresh(){await loadAll();$('#sideBusiness').textContent=state.business.business_name||'My Business';$('#userAvatar').textContent=(state.user.email||'U').slice(0,1).toUpperCase();const plan=currentPlan();$('#planBadge').textContent=plan.replaceAll('_',' ').toUpperCase();$('#planMiniText').textContent=plan==='free'?'Upgrade when your business needs more.':'Your plan is active.';render();}
function showAuth(){ $('#authScreen').classList.remove('hidden');$('#appShell').classList.add('hidden'); }
function showApp(){ $('#authScreen').classList.add('hidden');$('#appShell').classList.remove('hidden'); }
let signup=false;
$('#toggleAuth').onclick=()=>{signup=!signup;$('#nameField').classList.toggle('hidden',!signup);$('#authTitle').textContent=signup?'Create your account':'Welcome back';$('#authSub').textContent=signup?'Start your business workspace.':'Sign in to manage your business from anywhere.';$('#authSubmit').textContent=signup?'Create account':'Sign in';$('#toggleAuth').textContent=signup?'I already have an account':'Create account';$('#authPassword').autocomplete=signup?'new-password':'current-password';};
$('#authForm').onsubmit=async e=>{e.preventDefault();const email=$('#authEmail').value.trim(),password=$('#authPassword').value;$('#authSubmit').disabled=true;$('#authSubmit').textContent='Please wait…';try{if(signup){const {data,error}=await sb.auth.signUp({email,password,options:{data:{display_name:$('#authName').value.trim()}}});if(error)throw error;if(data.session){state.user=data.user;showApp();await refresh();}else toast('Account created. Check your email to confirm, then sign in.');}else{const {data,error}=await sb.auth.signInWithPassword({email,password});if(error)throw error;state.user=data.user;showApp();await refresh();}}catch(e){err(e)}finally{$('#authSubmit').disabled=false;$('#authSubmit').textContent=signup?'Create account':'Sign in';}};
$('#forgotBtn').onclick=async()=>{const email=$('#authEmail').value.trim();if(!email)return toast('Enter your email address first.');const {error}=await sb.auth.resetPasswordForEmail(email);if(error)err(error);else toast('Password reset email sent if the address exists.');};
$('#signOut').onclick=async()=>{await sb.auth.signOut();state.user=null;showAuth();};
$('#menuBtn').onclick=()=>$('#sidebar').classList.toggle('open');$('#themeBtn').onclick=()=>{state.theme=state.theme==='dark'?'light':'dark';applyTheme()};
$('#nav').onclick=e=>{const b=e.target.closest('[data-page]');if(b)setPage(b.dataset.page)};document.addEventListener('click',e=>{const b=e.target.closest('[data-go]');if(b)setPage(b.dataset.go);if(e.target.matches('[data-close]'))closeModal();});
function openModal(title,body,saveText='Save',onSave=null){$('#modalTitle').textContent=title;$('#modalBody').innerHTML=`${body}<div class="modal-actions"><button class="btn secondary" type="button" data-close="1">Cancel</button><button class="btn primary" type="button" id="modalSave">${saveText}</button></div>`;$('#modal').classList.remove('hidden');$('#modalSave').onclick=async()=>{if(onSave)await onSave();};}
function closeModal(){$('#modal').classList.add('hidden');$('#modalBody').innerHTML='';}
function formField(label,name,value='',type='text',extra=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`}
function selectField(label,name,options,value=''){return `<label>${label}<select name="${name}">${options.map(([v,t])=>`<option value="${v}" ${v===value?'selected':''}>${t}</option>`).join('')}</select></label>`}
function formData(){return Object.fromEntries(new FormData($('#modalForm')).entries())}
function modalForm(title,fields,save,callback){openModal(title,`<form id="modalForm" class="modal-form"><div class="form-grid">${fields}</div></form>`,save,async()=>{const f=$('#modalForm');if(!f.reportValidity())return;await callback(formData());});}
async function insert(table,obj){if((table==='customers'||table==='products')&&!checkFreeLimit(table))return;const {error}=await sb.from(table).insert({...obj,owner_id:state.user.id});if(error)throw error;await refresh();toast('Saved successfully.');}
async function update(table,id,obj){const {error}=await sb.from(table).update(obj).eq('id',id);if(error)throw error;await refresh();toast('Updated successfully.');}
async function remove(table,id){if(!confirm('Delete this record? This cannot be undone.'))return;const {error}=await sb.from(table).delete().eq('id',id);if(error)throw error;await refresh();toast('Deleted.');}
function pageHeader(title,sub,button='',action=''){return `<div class="section-head" style="margin-top:0"><div><h3>${title}</h3><div class="muted-small">${sub}</div></div>${button?`<button class="btn primary" data-action="${action}">＋ ${button}</button>`:''}</div>`}
function tableHtml(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows||'<tr><td colspan="8"><div class="empty">No records yet.</div></td></tr>'}</tbody></table></div>`}
function chartSvg(){const months=Array.from({length:6},(_,i)=>{const d=new Date();d.setMonth(d.getMonth()-5+i);return {key:d.toISOString().slice(0,7),label:d.toLocaleDateString('en-IN',{month:'short'})}});const vals=months.map(m=>({ ...m,rev:state.invoices.filter(x=>(x.issue_date||'').slice(0,7)===m.key&&x.status!=='cancelled').reduce((a,x)=>a+Number(x.total_amount||0),0),exp:state.expenses.filter(x=>(x.expense_date||'').slice(0,7)===m.key).reduce((a,x)=>a+Number(x.amount||0),0)}));const max=Math.max(1,...vals.flatMap(x=>[x.rev,x.exp]));const pts=(key)=>vals.map((v,i)=>`${28+i*90},${190-v[key]/max*150}`).join(' ');return `<div class="chart-wrap"><svg viewBox="0 0 500 220" role="img" aria-label="Six month revenue and expense trend"><line x1="25" y1="190" x2="485" y2="190" stroke="var(--line)"/><line x1="25" y1="115" x2="485" y2="115" stroke="var(--line)"/><line x1="25" y1="40" x2="485" y2="40" stroke="var(--line)"/><polyline points="${pts('rev')}" fill="none" stroke="#5268e8" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/> <polyline points="${pts('exp')}" fill="none" stroke="#e5a54b" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>${vals.map((v,i)=>`<text x="${28+i*90}" y="210" fill="var(--muted)" font-size="10" text-anchor="middle">${v.label}</text>`).join('')}</svg></div><div class="chart-legend"><span><i></i>Revenue</span><span><i class="orange"></i>Expenses</span></div>`}
function renderDashboard(){const total=state.invoices.filter(x=>x.status!=='cancelled').reduce((a,x)=>a+Number(x.total_amount||0),0),paid=state.invoices.reduce((a,x)=>a+Number(x.paid_amount||0),0),outstanding=Math.max(0,total-paid),expenses=state.expenses.reduce((a,x)=>a+Number(x.amount||0),0),profit=paid-expenses;const recent=[...state.invoices].slice(0,5).map(i=>{const c=state.customers.find(c=>c.id===i.customer_id);return `<tr><td><b>${esc(i.invoice_number)}</b></td><td>${esc(c?.name||'Walk-in')}</td><td>${date(i.issue_date)}</td><td>${money(i.total_amount)}</td><td><span class="status ${i.status}">${i.status}</span></td><td><button class="text-btn" data-action="view-invoice" data-id="${i.id}">View</button></td></tr>`}).join('');return `<div class="hero"><div><div class="eyebrow" style="color:#e3e7ff">BUSINESS SNAPSHOT</div><h2 style="margin-top:6px">Good to see you, ${esc(state.business.owner_name||'there')} 👋</h2><p>Here’s what’s happening with ${esc(state.business.business_name||'your business')}.</p></div><button class="btn" data-action="new-invoice">＋ Create invoice</button></div><div class="grid stats"><div class="card"><div class="stat-label">Total invoiced</div><div class="stat-value">${money(total)}</div><div class="stat-foot">All non-cancelled invoices</div></div><div class="card"><div class="stat-label">Payments received</div><div class="stat-value">${money(paid)}</div><div class="stat-foot">Recorded collections</div></div><div class="card"><div class="stat-label">Outstanding</div><div class="stat-value">${money(outstanding)}</div><div class="stat-foot">Remaining invoice balance</div></div><div class="card"><div class="stat-label">Net cash overview</div><div class="stat-value">${money(profit)}</div><div class="stat-foot">Received payments minus expenses</div></div></div><div class="grid two-col"><div class="card"><div class="section-head" style="margin:0 0 10px"><h3>Revenue & expenses</h3><span class="muted-small">Last 6 months</span></div>${chartSvg()}</div><div class="card"><div class="section-head" style="margin:0 0 15px"><h3>Quick actions</h3></div><div class="grid three-col"><button class="btn secondary" data-action="new-customer">＋ Customer</button><button class="btn secondary" data-action="new-product">＋ Product</button><button class="btn secondary" data-action="new-expense">＋ Expense</button></div><div class="section-head"><h3>Business pulse</h3></div><div class="row between"><span class="muted-small">Customers</span><b>${state.customers.length}</b></div><div class="progress"><span style="width:${Math.min(100,state.customers.length*5)}%"></span></div><div class="row between" style="margin-top:14px"><span class="muted-small">Products / services</span><b>${state.products.length}</b></div><div class="progress"><span style="width:${Math.min(100,state.products.length*5)}%"></span></div><div class="row between" style="margin-top:14px"><span class="muted-small">Low stock items</span><b>${state.products.filter(p=>Number(p.stock_quantity)<=Number(p.low_stock_threshold||5)).length}</b></div></div></div><div class="section-head"><h3>Recent invoices</h3><button class="text-btn" data-go="invoices">View all →</button></div>${tableHtml(['Invoice','Customer','Date','Amount','Status',''],recent)}`}
function renderCustomers(){const rows=state.customers.map(c=>`<tr><td><b>${esc(c.name)}</b></td><td>${esc(c.phone||'—')}</td><td>${esc(c.email||'—')}</td><td>${esc(c.address||'—')}</td><td><div class="actions"><button class="text-btn" data-action="edit-customer" data-id="${c.id}">Edit</button><button class="text-btn" data-action="delete" data-table="customers" data-id="${c.id}">Delete</button></div></td></tr>`).join('');return `${pageHeader('Customer directory','Manage customer contacts and billing details','Add customer','new-customer')}<div class="toolbar" style="margin-bottom:13px"><input id="searchTable" placeholder="Search customers…"></div><div id="filterTable">${tableHtml(['Customer','Phone','Email','Address','Actions'],rows)}</div>`}
function renderProducts(){const rows=state.products.map(p=>`<tr><td><b>${esc(p.name)}</b><div class="muted-small">${esc(p.sku||p.description||'')}${p.barcode?` · Barcode: ${esc(p.barcode)}`:''}</div></td><td>${money(p.unit_price)}</td><td>${Number(p.stock_quantity||0)} ${esc(p.unit||'pcs')}</td><td>${Number(p.stock_quantity)<=Number(p.low_stock_threshold||5)?'<span class="low-stock">Low stock</span>':'<span class="status paid">In stock</span>'}</td><td><div class="actions"><button class="text-btn" data-action="edit-product" data-id="${p.id}">Edit</button><button class="text-btn" data-action="delete" data-table="products" data-id="${p.id}">Delete</button></div></td></tr>`).join('');return `${pageHeader('Products & services','Set prices, SKUs and stock thresholds','Add item','new-product')}${tableHtml(['Item','Unit price','Stock','Stock status','Actions'],rows)}`}
function renderInventory(){const rows=state.products.map(p=>`<tr><td><b>${esc(p.name)}</b></td><td>${Number(p.stock_quantity)} ${esc(p.unit||'pcs')}</td><td>${Number(p.low_stock_threshold||5)} ${esc(p.unit||'pcs')}</td><td>${Number(p.stock_quantity)<=Number(p.low_stock_threshold||5)?'<span class="status overdue">Reorder</span>':'<span class="status paid">Healthy</span>'}</td><td><button class="text-btn" data-action="stock-move" data-id="${p.id}">Adjust stock</button></td></tr>`).join('');const history=state.movements.slice(0,8).map(m=>{const p=state.products.find(p=>p.id===m.product_id);return `<tr><td>${esc(p?.name||'Deleted item')}</td><td>${esc(m.movement_type.replace('_',' '))}</td><td>${m.quantity}</td><td>${date(m.created_at?.slice(0,10))}</td><td>${esc(m.note||'—')}</td></tr>`}).join('');return `${pageHeader('Inventory control','Track stock in, stock out and adjustments','Adjust stock','stock-move')}<div class="grid stats"><div class="card"><div class="stat-label">Tracked items</div><div class="stat-value">${state.products.length}</div></div><div class="card"><div class="stat-label">Low stock alerts</div><div class="stat-value">${state.products.filter(p=>Number(p.stock_quantity)<=Number(p.low_stock_threshold||5)).length}</div></div><div class="card"><div class="stat-label">Units in stock</div><div class="stat-value">${state.products.reduce((a,p)=>a+Number(p.stock_quantity||0),0)}</div></div><div class="card"><div class="stat-label">Stock movements</div><div class="stat-value">${state.movements.length}</div></div></div><div class="section-head"><h3>Current stock</h3></div>${tableHtml(['Product','Available','Alert below','Status',''],rows)}<div class="section-head"><h3>Recent stock movements</h3></div>${tableHtml(['Product','Movement','Quantity','Date','Note'],history)}`}
function renderExpenses(){const rows=state.expenses.map(x=>`<tr><td><b>${esc(x.title)}</b></td><td>${esc(x.category||'Other')}</td><td>${date(x.expense_date)}</td><td>${money(x.amount)}</td><td><button class="text-btn" data-action="delete" data-table="expenses" data-id="${x.id}">Delete</button></td></tr>`).join('');return `${pageHeader('Expenses','Record and categorise business spending','Add expense','new-expense')}<div class="card" style="margin-bottom:14px"><div class="stat-label">Total recorded expenses</div><div class="stat-value">${money(state.expenses.reduce((a,x)=>a+Number(x.amount),0))}</div></div>${tableHtml(['Expense','Category','Date','Amount',''],rows)}`}
function renderInvoices(){const rows=state.invoices.map(i=>{const c=state.customers.find(c=>c.id===i.customer_id);return `<tr><td><b>${esc(i.invoice_number)}</b></td><td>${esc(c?.name||'Walk-in')}</td><td>${date(i.issue_date)}</td><td>${date(i.due_date)}</td><td>${money(i.total_amount)}</td><td><span class="status ${i.status}">${i.status}</span></td><td><div class="actions"><button class="text-btn" data-action="view-invoice" data-id="${i.id}">View</button><button class="text-btn" data-action="record-payment" data-id="${i.id}">Payment</button><button class="text-btn" data-action="remind" data-id="${i.id}">Remind</button></div></td></tr>`}).join('');const payRows=state.payments.map(p=>{const inv=state.invoices.find(i=>i.id===p.invoice_id);return `<tr><td>${esc(inv?.invoice_number||'Invoice')}</td><td>${date(p.payment_date)}</td><td>${money(p.amount)}</td><td>${esc(p.method||'—')}</td><td>${esc(p.reference||'—')}</td></tr>`}).join('');return `${pageHeader('Invoices & payments','Create multi-item invoices, track collections and send reminders','New invoice','new-invoice')}<div class="grid stats"><div class="card"><div class="stat-label">Invoices</div><div class="stat-value">${state.invoices.length}</div></div><div class="card"><div class="stat-label">Collected</div><div class="stat-value">${money(state.invoices.reduce((a,i)=>a+Number(i.paid_amount||0),0))}</div></div><div class="card"><div class="stat-label">Outstanding</div><div class="stat-value">${money(state.invoices.reduce((a,i)=>a+Math.max(0,Number(i.total_amount)-Number(i.paid_amount||0)),0))}</div></div><div class="card"><div class="stat-label">Payment entries</div><div class="stat-value">${state.payments.length}</div></div></div>${tableHtml(['Invoice','Customer','Issue date','Due date','Total','Status','Actions'],rows)}<div class="section-head"><h3>Payment history</h3></div>${tableHtml(['Invoice','Payment date','Amount','Method','Reference'],payRows)}`}
function renderReports(){const total=state.invoices.filter(i=>i.status!=='cancelled').reduce((a,i)=>a+Number(i.total_amount),0),tax=state.invoices.reduce((a,i)=>a+Number(i.tax_amount||0),0),paid=state.invoices.reduce((a,i)=>a+Number(i.paid_amount||0),0),exp=state.expenses.reduce((a,i)=>a+Number(i.amount),0);return `${pageHeader('Reports & GST','Business performance, tax summary and downloadable data','Export GST CSV','gst-export')}<div class="grid stats"><div class="card"><div class="stat-label">Gross invoiced</div><div class="stat-value">${money(total)}</div></div><div class="card"><div class="stat-label">Tax collected / invoiced</div><div class="stat-value">${money(tax)}</div></div><div class="card"><div class="stat-label">Payments received</div><div class="stat-value">${money(paid)}</div></div><div class="card"><div class="stat-label">Expenses</div><div class="stat-value">${money(exp)}</div></div></div><div class="grid two-col"><div class="card"><h3>GST overview</h3><p class="muted-small">Summary of tax recorded on invoices. Use this as a management report and verify figures with your accountant before filing returns.</p><div class="row between" style="margin-top:18px"><span class="muted-small">Business GSTIN</span><b>${esc(state.business.gstin||'Not added')}</b></div><div class="row between" style="margin-top:12px"><span class="muted-small">Default tax rate</span><b>${Number(state.business.tax_rate||0)}%</b></div><div class="row between" style="margin-top:12px"><span class="muted-small">Total tax on invoices</span><b>${money(tax)}</b></div><button class="btn secondary" style="margin-top:20px" data-action="gst-export">Download invoice tax CSV</button></div><div class="card"><h3>Profit overview</h3><div class="stat-value">${money(paid-exp)}</div><p class="muted-small">Recorded receipts minus recorded expenses. This is a cash overview, not audited accounting profit.</p><div class="row between"><span class="muted-small">Receipts</span><b>${money(paid)}</b></div><div class="row between" style="margin-top:10px"><span class="muted-small">Expenses</span><b>${money(exp)}</b></div><div class="row between" style="margin-top:10px"><span class="muted-small">Outstanding invoices</span><b>${money(total-paid)}</b></div></div></div><div class="section-head"><h3>Monthly trend</h3></div><div class="card">${chartSvg()}</div><div class="section-head"><h3>Data exports</h3></div><div class="toolbar"><button class="btn secondary" data-action="export-backup">Export full backup (JSON)</button><button class="btn secondary" data-action="export-invoices">Export invoices (CSV)</button><button class="btn secondary" data-action="export-expenses">Export expenses (CSV)</button></div>`}
function renderPlans(){const current=currentPlan();const plans=[['free','Free','₹0','For getting started','3 invoices/month · 25 customers · 25 products'],['pro_monthly','Pro Monthly','₹39','Unlock the full BizMitra toolkit','Unlimited invoices, customers and products'],['pro_yearly','Pro Yearly','₹299','All Pro features with yearly pricing','Unlimited invoices, customers and products'],['lifetime','Lifetime','₹999','One-time plan for long-term use','All Pro features for lifetime']];return `${pageHeader('Plans & billing','Choose the plan that fits your business')}<div class="notice">Free plan limits are active. Pro features are locked until a paid plan is activated. Payments are not connected yet, so requesting an upgrade does not activate Pro.</div><div class="grid stats" style="grid-template-columns:repeat(4,minmax(0,1fr));margin-top:18px">${plans.map(([id,n,price,desc,foot])=>`<div class="card plan-card"><span class="pill ${id===current?'good':'free'}">${id===current?'CURRENT PLAN':'BIZMITRA PLAN'}</span><h3 style="margin-top:14px">${n}</h3><div class="plan-price">${price}</div><p class="muted-small">${desc}</p><ul class="feature-list"><li>${foot}</li><li>${id==='free'?'Classic invoice template':'All 4 invoice templates'}</li><li>${id==='free'?'Manual reminders':'Barcode camera, CSV/GST exports and advanced reminders'}</li><li>Cloud sync with your account</li></ul><button class="btn ${id===current?'secondary':'primary'} full" ${id===current?'disabled':''} data-action="plan-request" data-plan="${id}">${id===current?'Current plan':'Request upgrade'}</button></div>`).join('')}</div><div class="card" style="margin-top:16px"><b>Free plan restrictions</b><p class="muted-small">3 invoices per calendar month (used this month: ${invoicesThisMonth()}/3), up to 25 customers and 25 products/services. Free users can use the Classic invoice design, basic business overview, manual reminders and full JSON backup. Pro unlocks the other invoice designs, camera barcode scanning, GST/CSV exports and WhatsApp/email reminder preparation.</p></div>`}
function renderSettings(){const b=state.business||{};return `${pageHeader('Business settings','Update your business identity, invoice defaults and brand')}<div class="card"><form id="settingsForm" class="modal-form"><div class="form-grid">${formField('Business name','business_name',b.business_name)}${formField('Owner name','owner_name',b.owner_name)}${formField('Email','email',b.email||state.user.email,'email')}${formField('Phone','phone',b.phone,'tel')}${formField('GSTIN','gstin',b.gstin)}${formField('State code','state_code',b.state_code)}${formField('Currency code','currency',b.currency||'INR')}${formField('Default tax rate (%)','tax_rate',b.tax_rate||0,'number','min="0" max="100" step="0.01"')}${formField('Invoice prefix','invoice_prefix',b.invoice_prefix||'BM')}${formField('Payment terms','payment_terms',b.payment_terms||'Due within 15 days') }<label class="wide">Business address<textarea name="address">${esc(b.address||'')}</textarea></label><label class="wide">Business logo<input type="file" id="logoFile" accept="image/png,image/jpeg,image/webp"><small class="muted-small">Image is stored in your business profile. Keep it under 500 KB.</small></label>${b.logo_data_url?`<div class="wide"><img src="${b.logo_data_url}" style="max-width:110px;max-height:65px;object-fit:contain" alt="Business logo"></div>`:''}</div><div class="modal-actions"><button class="btn primary" type="submit">Save business settings</button></div></form></div><div class="section-head"><h3>Backup & restore</h3></div><div class="card"><p class="muted-small">Export a complete JSON backup or restore a backup created by BizMitra V2. Restore replaces records in your current workspace, so export a backup first.</p><div class="toolbar"><button class="btn secondary" data-action="export-backup">Export backup</button><label class="btn secondary" style="display:inline-flex;align-items:center;cursor:pointer">Restore JSON<input type="file" id="restoreFile" accept="application/json" hidden></label></div></div><div class="section-head"><h3>Account</h3></div><div class="card"><div class="row between"><div><b>${esc(state.user.email)}</b><p class="muted-small">Signed in to your private workspace</p></div><button class="btn danger" id="settingsSignout">Sign out</button></div></div>`}
function render(){if(!state.user)return;applyTheme();const map={dashboard:renderDashboard,invoices:renderInvoices,customers:renderCustomers,products:renderProducts,inventory:renderInventory,expenses:renderExpenses,reports:renderReports,plans:renderPlans,settings:renderSettings};$('#content').innerHTML=(map[state.page]||renderDashboard)();bindPage();}
function bindPage(){const search=$('#searchTable');if(search)search.oninput=()=>{const q=search.value.toLowerCase();$$('#filterTable tbody tr').forEach(r=>r.style.display=r.textContent.toLowerCase().includes(q)?'':'none')};const sf=$('#settingsForm');if(sf)sf.onsubmit=async e=>{e.preventDefault();try{const d=Object.fromEntries(new FormData(sf).entries());d.tax_rate=Number(d.tax_rate||0);const file=$('#logoFile').files[0];if(file){if(file.size>500000)throw new Error('Logo must be under 500 KB.');d.logo_data_url=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(file)})}const {error}=await sb.from('businesses').update(d).eq('id',state.business.id);if(error)throw error;await refresh();toast('Business settings saved.')}catch(e){err(e)}};const so=$('#settingsSignout');if(so)so.onclick=()=>$('#signOut').click();const rf=$('#restoreFile');if(rf)rf.onchange=()=>restoreBackup(rf.files[0]);}
function customerFields(c={}){return `${formField('Customer name','name',c.name||'','text','required')}${formField('Phone','phone',c.phone||'','tel')}${formField('Email','email',c.email||'','email') }<label class="wide">Address<textarea name="address">${esc(c.address||'')}</textarea></label><label class="wide">Notes<textarea name="notes">${esc(c.notes||'')}</textarea></label>`}
function productFields(p={}){return `${formField('Item name','name',p.name||'','text','required')}${formField('SKU','sku',p.sku||'')}${formField('Barcode','barcode',p.barcode||'','text','inputmode=\"numeric\"')}${formField('Unit price','unit_price',p.unit_price||0,'number','min="0" step="0.01" required')}${formField('Opening stock','stock_quantity',p.stock_quantity||0,'number','min="0" step="0.01"')}${formField('Unit','unit',p.unit||'pcs')}${formField('Low stock alert below','low_stock_threshold',p.low_stock_threshold??5,'number','min="0" step="0.01"')}<label class="wide">Description<textarea name="description">${esc(p.description||'')}</textarea></label>`}
function expenseFields(x={}){return `${formField('Expense title','title',x.title||'','text','required')}${formField('Amount','amount',x.amount||'','number','min="0.01" step="0.01" required')}${selectField('Category','category',['Rent','Utilities','Travel','Supplies','Salary','Marketing','Other'].map(x=>[x,x]),x.category||'Other')}${formField('Date','expense_date',x.expense_date||today(),'date','required')}<label class="wide">Notes<textarea name="notes">${esc(x.notes||'')}</textarea></label>`}
function openInvoice(){if(!checkFreeLimit('invoices'))return;if(!state.customers.length)return toast('Add a customer before creating an invoice.');if(!state.products.length)return toast('Add a product or service before creating an invoice.');const customerOpts=state.customers.map(c=>[c.id,c.name]);const productOpts=state.products.map(p=>[p.id,p.name]);const templateOpts=isPro()?[['classic','Classic'],['modern','Modern'],['minimal','Minimal'],['bold','Bold']]:[['classic','Classic']];const fields=`${selectField('Customer','customer_id',customerOpts)}${formField('Invoice number','invoice_number',`${state.business.invoice_prefix||'BM'}-${String(state.invoices.length+1).padStart(4,'0')}`,'text','required')}${formField('Issue date','issue_date',today(),'date','required')}${formField('Due date','due_date',today(),'date')}${selectField('Invoice template','template_key',templateOpts,'classic')}${selectField('Tax calculation','tax_type',[['exclusive','Tax extra'],['inclusive','Tax included']],'exclusive')}<label>Scan / enter product barcode or SKU<div class="barcode-entry"><input id="invoiceBarcode" placeholder="Scan or type barcode / SKU" autocomplete="off"><button type="button" class="btn secondary small" id="scanInvoiceBarcode">Scan camera</button><button type="button" class="btn secondary small" id="addBarcodeProduct">Add</button></div><small class="muted-small">Repeated scans increase quantity. You can also add invoice lines manually below.</small></label><label>Line items<div id="invoiceLines" class="stack" style="margin-top:7px"></div><button type="button" class="btn secondary small" id="addLine">＋ Add another line</button></label>${formField('Notes','notes','','text')}`;modalForm('Create invoice',fields,'Create invoice',async d=>{try{if(!checkFreeLimit('invoices'))return;if(!isPro()&&d.template_key!=='classic')throw new Error('Only the Classic invoice template is available on Free.');const lines=$$('#invoiceLines .invoice-line').map(el=>({product_id:el.querySelector('select').value,quantity:Number(el.querySelector('[name=qty]').value),unit_price:Number(el.querySelector('[name=price]').value)}));if(!lines.length||lines.some(x=>!x.quantity||x.quantity<=0||x.unit_price<0))throw new Error('Enter valid invoice line items.');const sub=lines.reduce((a,x)=>a+x.quantity*x.unit_price,0),rate=Number(state.business.tax_rate||0),tax=d.tax_type==='inclusive'?sub-(sub/(1+rate/100)):sub*rate/100,total=d.tax_type==='inclusive'?sub:sub+tax;const {data:inv,error}=await sb.from('invoices').insert({owner_id:state.user.id,customer_id:d.customer_id,invoice_number:d.invoice_number,issue_date:d.issue_date,due_date:d.due_date||null,status:'unpaid',subtotal:sub,tax_amount:tax,total_amount:total,notes:d.notes,tax_type:d.tax_type,template_key:d.template_key,paid_amount:0}).select().single();if(error)throw error;const payload=lines.map(l=>{const p=state.products.find(p=>p.id===l.product_id);return {owner_id:state.user.id,invoice_id:inv.id,item_name:p.name,description:p.description,quantity:l.quantity,unit_price:l.unit_price,line_total:l.quantity*l.unit_price}});const {error:ie}=await sb.from('invoice_items').insert(payload);if(ie){await sb.from('invoices').delete().eq('id',inv.id);throw ie;}closeModal();await refresh();toast('Invoice created.');}catch(e){err(e)}});const add=()=>{const div=document.createElement('div');div.className='invoice-line form-grid';div.innerHTML=`${selectField('Product / service','product_id',productOpts)}${formField('Quantity','qty',1,'number','min="0.01" step="0.01" required')}${formField('Unit price','price',state.products[0]?.unit_price||0,'number','min="0" step="0.01" required')}<button type="button" class="text-btn remove-line">Remove line</button>`;$('#invoiceLines').append(div);div.querySelector('select').onchange=e=>{const p=state.products.find(x=>x.id===e.target.value);div.querySelector('[name=price]').value=p?.unit_price||0};div.querySelector('.remove-line').onclick=()=>div.remove()};const addProductLine=(product)=>{const existing=$$('#invoiceLines .invoice-line').find(el=>el.dataset.productId===product.id);if(existing){const q=existing.querySelector('[name=qty]');q.value=Number(q.value||0)+1;toast(`${product.name}: quantity increased.`);return;}const div=document.createElement('div');div.className='invoice-line form-grid';div.dataset.productId=product.id;div.innerHTML=`${selectField('Product / service','product_id',productOpts,product.id)}${formField('Quantity','qty',1,'number','min="0.01" step="0.01" required')}${formField('Unit price','price',product.unit_price||0,'number','min="0" step="0.01" required')}<button type="button" class="text-btn remove-line">Remove line</button>`;$('#invoiceLines').append(div);div.querySelector('select').onchange=e=>{const pr=state.products.find(x=>x.id===e.target.value);div.dataset.productId=e.target.value;div.querySelector('[name=price]').value=pr?.unit_price||0};div.querySelector('.remove-line').onclick=()=>div.remove();};
const addFirstLine=()=>addProductLine(state.products[0]);addFirstLine();$('#addLine').onclick=add;const findBarcode=()=>{const val=$('#invoiceBarcode').value.trim().toLowerCase();if(!val)return;const product=state.products.find(x=>(x.barcode||'').toLowerCase()===val||(x.sku||'').toLowerCase()===val);if(product){addProductLine(product);$('#invoiceBarcode').value='';return;}if(confirm('No saved product matches this barcode/SKU. Create a product with this code?'))createProductFromBarcode(val,()=>{const created=state.products.find(x=>(x.barcode||'').toLowerCase()===val||(x.sku||'').toLowerCase()===val);if(created)addProductLine(created);});};$('#addBarcodeProduct').onclick=findBarcode;$('#invoiceBarcode').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();findBarcode();}};$('#scanInvoiceBarcode').onclick=()=>{if(requirePro('Camera barcode scanning'))scanBarcode(code=>{ $('#invoiceBarcode').value=code;findBarcode(); });};}

function createProductFromBarcode(code,onCreated){modalForm('Create product from barcode',`${formField('Product name','name','','text','required')}${formField('Barcode','barcode',code,'text','required')}${formField('SKU','sku',code)}${formField('Unit price','unit_price',0,'number','min="0" step="0.01" required')}${formField('Opening stock','stock_quantity',0,'number','min="0" step="0.01"')}${formField('Unit','unit','pcs')}${formField('Low stock alert below','low_stock_threshold',5,'number','min="0" step="0.01"')}`, 'Save product',async d=>{try{d.unit_price=Number(d.unit_price);d.stock_quantity=Number(d.stock_quantity);d.low_stock_threshold=Number(d.low_stock_threshold);d.barcode=(d.barcode||'').trim()||null;await insert('products',d);closeModal();if(onCreated)onCreated();}catch(e){err(e)}});}
async function scanBarcode(onDetected){if(!('BarcodeDetector' in window)){toast('Camera barcode detection is not supported here. Type the barcode manually.');$('#invoiceBarcode')?.focus();return;}let stream;try{const detector=new BarcodeDetector({formats:['ean_13','ean_8','upc_a','upc_e','code_128','code_39','qr_code']});stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}}});const video=document.createElement('video');video.autoplay=true;video.playsInline=true;video.srcObject=stream;await video.play();openModal('Scan barcode',`<div class="scanner-wrap"><video id="barcodeVideo" autoplay playsinline></video><p class="muted-small">Hold the barcode inside the camera view. If scanning doesn't work, close and enter it manually.</p></div>`,'Close',async()=>closeModal());$('#modalSave').textContent='Close';const live=$('#barcodeVideo');live.srcObject=stream;let stopped=false;const stop=()=>{stopped=true;stream?.getTracks().forEach(t=>t.stop());};$('#modalSave').onclick=()=>{stop();closeModal()};const tick=async()=>{if(stopped)return;try{const codes=await detector.detect(live);if(codes.length&&codes[0].rawValue){const value=codes[0].rawValue;stop();closeModal();onDetected(value);return;}}catch(e){}requestAnimationFrame(tick)};requestAnimationFrame(tick);$('#modal').querySelector('[data-close]')?.addEventListener('click',stop,{once:true});}catch(e){stream?.getTracks().forEach(t=>t.stop());toast('Camera permission or camera access failed. Enter the barcode manually.');}}
async function viewInvoice(id){const inv=state.invoices.find(x=>x.id===id);if(!inv)return;const c=state.customers.find(x=>x.id===inv.customer_id)||{},lines=state.items.filter(x=>x.invoice_id===id);const logo=state.business.logo_data_url?`<img class="invoice-logo" src="${state.business.logo_data_url}">`:'';const html=`<div id="printArea" class="invoice-paper template-${esc(inv.template_key||'classic')}"><div class="invoice-head"><div>${logo}<h2>${esc(state.business.business_name)}</h2><p>${esc(state.business.address||'') }<br>${esc(state.business.phone||'')} · ${esc(state.business.email||'')}<br>${state.business.gstin?'GSTIN: '+esc(state.business.gstin):''}</p></div><div style="text-align:right"><h2>INVOICE</h2><b>${esc(inv.invoice_number)}</b><p>Issue: ${date(inv.issue_date)}<br>Due: ${date(inv.due_date)}</p></div></div><div style="margin-bottom:20px"><b>Bill to</b><p>${esc(c.name||'Walk-in')}<br>${esc(c.address||'')}<br>${esc(c.phone||'')} ${esc(c.email||'')}</p></div><table><thead><tr><th>Item</th><th>Qty</th><th>Rate</th><th>Amount</th></tr></thead><tbody>${lines.map(l=>`<tr><td>${esc(l.item_name)}<div class="muted-small">${esc(l.description||'')}</div></td><td>${l.quantity}</td><td>${money(l.unit_price)}</td><td>${money(l.line_total)}</td></tr>`).join('')}</tbody></table><div style="margin:20px 0 0 auto;max-width:260px"><div class="row between"><span>Subtotal</span><b>${money(inv.subtotal)}</b></div><div class="row between"><span>Tax</span><b>${money(inv.tax_amount)}</b></div><div class="row between" style="font-size:18px;margin-top:12px;border-top:1px solid #ddd;padding-top:12px"><b>Total</b><b>${money(inv.total_amount)}</b></div><div class="row between"><span>Paid</span><b>${money(inv.paid_amount)}</b></div><div class="row between"><span>Balance</span><b>${money(Math.max(0,inv.total_amount-(inv.paid_amount||0)))}</b></div></div><p style="margin-top:30px">${esc(inv.notes||state.business.payment_terms||'Thank you for your business.')}</p></div><div class="toolbar" style="margin-top:15px"><button class="btn primary" id="printInvoice">Print / Save PDF</button><button class="btn secondary" id="shareInvoice">Share invoice</button><button class="btn secondary" id="paymentFromView">Record payment</button></div>`;openModal('Invoice preview',html,'Close',async()=>closeModal());$('#modalSave').textContent='Close';$('#printInvoice').onclick=()=>{const content=$('#printArea').outerHTML;const w=window.open('','_blank');if(!w)return toast('Allow pop-ups to print this invoice.');w.document.write(`<html><head><title>${esc(inv.invoice_number)}</title><style>body{font:14px Arial;padding:25px;color:#172033}.invoice-paper{max-width:850px;margin:auto}.invoice-head{display:flex;justify-content:space-between;border-bottom:2px solid #5268e8;padding-bottom:15px;margin-bottom:20px}.invoice-head p{font-size:12px;line-height:1.5}table{width:100%;border-collapse:collapse}th,td{text-align:left;border-bottom:1px solid #ddd;padding:10px}th{background:#f5f6fa}.row{display:flex;justify-content:space-between;margin:8px 0}.invoice-logo{max-width:90px;max-height:60px}</style></head><body>${content}<script>window.onload=()=>window.print()<\/script></body></html>`);w.document.close()};$('#shareInvoice').onclick=async()=>{const text=`Invoice ${inv.invoice_number} from ${state.business.business_name}: ${money(inv.total_amount)}. Balance: ${money(inv.total_amount-(inv.paid_amount||0))}.`;if(navigator.share)await navigator.share({title:inv.invoice_number,text});else{await navigator.clipboard.writeText(text);toast('Invoice summary copied.')}};$('#paymentFromView').onclick=()=>{closeModal();recordPayment(id)};}
function recordPayment(id){const inv=state.invoices.find(x=>x.id===id),balance=Math.max(0,Number(inv.total_amount)-Number(inv.paid_amount||0));if(!balance)return toast('This invoice is fully paid.');modalForm('Record payment',`${formField('Amount received','amount',balance,'number',`min="0.01" max="${balance}" step="0.01" required`)}${selectField('Payment method','method',[['Cash','Cash'],['UPI','UPI'],['Bank transfer','Bank transfer'],['Card','Card'],['Other','Other']])}${formField('Payment date','payment_date',today(),'date','required')}${formField('Reference','reference')}`, 'Save payment',async d=>{try{const amount=Number(d.amount);if(amount>balance)throw new Error('Payment cannot exceed the outstanding balance.');const {error}=await sb.from('payment_records').insert({owner_id:state.user.id,invoice_id:id,amount,payment_date:d.payment_date,method:d.method,reference:d.reference});if(error)throw error;const newPaid=Number(inv.paid_amount||0)+amount;const {error:ue}=await sb.from('invoices').update({paid_amount:newPaid,status:newPaid>=Number(inv.total_amount)?'paid':'unpaid'}).eq('id',id);if(ue)throw ue;closeModal();await refresh();toast('Payment recorded.')}catch(e){err(e)}})}
function remindInvoice(id){const inv=state.invoices.find(x=>x.id===id),c=state.customers.find(x=>x.id===inv.customer_id)||{},bal=Math.max(0,inv.total_amount-(inv.paid_amount||0));const msg=`Hello ${c.name||'there'}, this is a friendly reminder that invoice ${inv.invoice_number} from ${state.business.business_name} has an outstanding balance of ${money(bal)}. Due date: ${date(inv.due_date)}. Thank you.`;modalForm('Payment reminder',`${formField('Reminder date','reminder_date',today(),'date','required')}${selectField('Channel','channel',isPro()?[['manual','Manual'],['whatsapp','WhatsApp'],['email','Email']]:[['manual','Manual']])}<label class="wide">Message<textarea name="message">${esc(msg)}</textarea></label>`,'Create reminder',async d=>{try{const {error}=await sb.from('payment_reminders').insert({owner_id:state.user.id,invoice_id:id,reminder_date:d.reminder_date,channel:d.channel,status:'pending',message:d.message});if(error)throw error;closeModal();await refresh();if(d.channel==='whatsapp'&&c.phone)window.open(`https://wa.me/${c.phone.replace(/\D/g,'')}?text=${encodeURIComponent(d.message)}`,'_blank');else if(d.channel==='email'&&c.email)window.location.href=`mailto:${c.email}?subject=${encodeURIComponent('Payment reminder '+inv.invoice_number)}&body=${encodeURIComponent(d.message)}`;toast('Reminder saved. Review and send it manually.')}catch(e){err(e)}})}
function stockMove(id){const p=id?state.products.find(x=>x.id===id):state.products[0];if(!p)return toast('Add a product first.');modalForm('Adjust inventory',`${selectField('Product','product_id',state.products.map(p=>[p.id,p.name]),p.id)}${selectField('Movement','movement_type',[['stock_in','Stock in'],['stock_out','Stock out'],['adjustment','Set exact stock']])}${formField('Quantity','quantity',1,'number','min="0.01" step="0.01" required')}<label class="wide">Note<textarea name="note"></textarea></label>`,'Update stock',async d=>{try{const prod=state.products.find(x=>x.id===d.product_id),qty=Number(d.quantity);let next=Number(prod.stock_quantity||0);if(d.movement_type==='stock_in')next+=qty;else if(d.movement_type==='stock_out')next-=qty;else next=qty;if(next<0)throw new Error('Stock cannot become negative.');const {error}=await sb.from('products').update({stock_quantity:next}).eq('id',prod.id);if(error)throw error;const {error:me}=await sb.from('inventory_movements').insert({owner_id:state.user.id,product_id:prod.id,movement_type:d.movement_type,quantity:qty,note:d.note});if(me)throw me;closeModal();await refresh();toast('Stock updated.')}catch(e){err(e)}})}
function exportCSV(name,rows){if(!rows.length)return toast('No data to export.');const cols=[...new Set(rows.flatMap(x=>Object.keys(x)))],csv=[cols.join(','),...rows.map(r=>cols.map(c=>`"${String(r[c]??'').replace(/"/g,'""')}"`).join(','))].join('\n');download(`${name}.csv`,csv,'text/csv')}
function download(name,content,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();URL.revokeObjectURL(url)}
function exportBackup(){const data={app:'BizMitra',version:2,exported_at:new Date().toISOString(),business:state.business,subscription:state.subscription};tables.forEach(t=>data[t]=state[t]);download(`BizMitra-backup-${today()}.json`,JSON.stringify(data,null,2),'application/json')}
async function restoreBackup(file){if(!file)return;try{if(!confirm('Restore replaces your current customers, products, invoices, invoice items, expenses and related records. Export a backup first. Continue?'))return;const data=JSON.parse(await file.text());if(data.app!=='BizMitra'||!data.version)throw new Error('This is not a BizMitra backup.');for(const t of [...tables].reverse()){const {error}=await sb.from(t).delete().eq('owner_id',state.user.id);if(error)throw error;}for(const t of ['customers','products','invoices','invoice_items','expenses','payment_records','inventory_movements','payment_reminders']){const rows=data[t]||[];for(let i=0;i<rows.length;i+=100){const payload=rows.slice(i,i+100).map(r=>({...r,owner_id:state.user.id}));if(payload.length){const {error}=await sb.from(t).insert(payload);if(error)throw error;}}}if(data.business){const {error}=await sb.from('businesses').update(data.business).eq('owner_id',state.user.id);if(error)throw error;}await refresh();toast('Backup restored.');}catch(e){err(e)}}
function handleAction(a){const id=a.dataset.id;try{switch(a.dataset.action){case'new-customer':modalForm('Add customer',customerFields(),'Save customer',async d=>{await insert('customers',d);closeModal()});break;case'edit-customer':{const c=state.customers.find(x=>x.id===id);modalForm('Edit customer',customerFields(c),'Save changes',async d=>{await update('customers',id,d);closeModal()});break;}case'new-product':modalForm('Add product or service',productFields(),'Save item',async d=>{d.unit_price=Number(d.unit_price);d.stock_quantity=Number(d.stock_quantity);d.low_stock_threshold=Number(d.low_stock_threshold);await insert('products',d);closeModal()});break;case'edit-product':{const p=state.products.find(x=>x.id===id);modalForm('Edit item',productFields(p),'Save changes',async d=>{d.unit_price=Number(d.unit_price);d.stock_quantity=Number(d.stock_quantity);d.low_stock_threshold=Number(d.low_stock_threshold);d.barcode=(d.barcode||'').trim()||null;await update('products',id,d);closeModal()});break;}case'new-expense':modalForm('Add expense',expenseFields(),'Save expense',async d=>{d.amount=Number(d.amount);await insert('expenses',d);closeModal()});break;case'new-invoice':openInvoice();break;case'view-invoice':viewInvoice(id);break;case'record-payment':recordPayment(id);break;case'remind':remindInvoice(id);break;case'stock-move':stockMove(id);break;case'delete':remove(a.dataset.table,id).catch(err);break;case'export-backup':exportBackup();break;case'export-invoices':if(requirePro('Invoice CSV export'))exportCSV('BizMitra-invoices',state.invoices);break;case'export-expenses':if(requirePro('Expense CSV export'))exportCSV('BizMitra-expenses',state.expenses);break;case'gst-export':if(!requirePro('GST summary CSV export'))break;exportCSV('BizMitra-GST-invoice-summary',state.invoices.map(i=>({invoice_number:i.invoice_number,issue_date:i.issue_date,customer:state.customers.find(c=>c.id===i.customer_id)?.name||'',subtotal:i.subtotal,tax_amount:i.tax_amount,total_amount:i.total_amount,status:i.status})));break;case'plan-request':toast('Paid checkout is not enabled. Your plan has not changed.');break;}}catch(e){err(e)}}
document.addEventListener('click',e=>{const a=e.target.closest('[data-action]');if(a)handleAction(a)});
let installPrompt=null;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;const b=$('#installBtn');if(b)b.hidden=false;});document.addEventListener('DOMContentLoaded',()=>{const b=$('#installBtn');if(b)b.onclick=async()=>{if(!installPrompt){toast('Use your browser menu → Install app / Add to Home screen.');return;}installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;b.hidden=true;};});if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(e=>console.warn('PWA service worker:',e)));
async function boot(){applyTheme();const {data:{session}}=await sb.auth.getSession();if(session){state.user=session.user;showApp();try{await refresh()}catch(e){err(e);$('#content').innerHTML='<div class="card"><h3>Could not load your workspace</h3><p class="muted-small">Check your Supabase project settings and table access, then reload.</p><button class="btn primary" onclick="location.reload()">Retry</button></div>'}}else showAuth();sb.auth.onAuthStateChange((_event,session)=>{if(!session){state.user=null;showAuth()}else if(!state.user){state.user=session.user;showApp();refresh().catch(err)}});}
boot();
